    private static function reduceLexerDeclaration(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        \assert(\is_array($children));

        $declaration = $children[0] ?? null;
        $lexer = $children[1] ?? null;

        \assert($declaration instanceof \Phplrt\Lexer\Token\Token);
        \assert($lexer instanceof \Phplrt\Compiler\Node\Reducer\CodeReducer);

        $name = $declaration->captures[0] ?? '';

        if ($name === '') {
            throw \Phplrt\Parser\Exception\UnexpectedTokenException::becauseUnexpectedTokenProduced($ctx->source, $declaration);
        }

        return new \Phplrt\Compiler\Node\Declaration\LexerDeclaration(
            name: $name,
            lexer: $lexer,
            offset: $declaration->offset,
            length: \max(0, $lexer->offset + $lexer->length - $declaration->offset),
        );
    }

    private static function reduceCodeReducer(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        \assert($children instanceof \Phplrt\Lexer\Token\TokenEmbedding);

        $read = $children->children;
        $code = '';

        // Note: The braces are the first and the last of the tokens read, so
        //       everything between them is the code itself.
        for ($i = 1, $last = \count($read) - 1; $i < $last; ++$i) {
            $code .= $read[$i]->value;
        }

        $lines = \explode("\n", $code);

        foreach ($lines as $index => $line) {
            $lines[$index] = $index === 0
                ? \ltrim($line)
                : \preg_replace('/^ {1,4}/', '', $line);
        }

        return new \Phplrt\Compiler\Node\Reducer\CodeReducer(
            code: \trim(\implode("\n", $lines)),
            offset: $children->offset,
            length: $children->size,
        );
    }

    private static function reduceRuleDeclaration(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        \assert(\is_array($children));

        $isKept = ($children[0] ?? null) === true;

        if ($isKept) {
            \array_shift($children);
        }

        $name = \array_shift($children);
        $body = \array_pop($children);

        $annotations = [];

        // What is said about the rule is written after its name, so it is read off
        // the front until the reducer is reached
        while (($annotation = $children[0] ?? null) instanceof \Phplrt\Compiler\Node\Annotation) {
            $annotations[] = $annotation;

            \array_shift($children);
        }

        $reducer = \array_pop($children);

        \assert($name instanceof \Phplrt\Contracts\Lexer\TokenInterface);
        \assert($name->value !== '', 'The lexer never produces an empty token');
        \assert($body instanceof \Phplrt\Compiler\Node\Statement\Statement);
        \assert($reducer === null || $reducer instanceof \Phplrt\Compiler\Node\Reducer\Reducer);

        return new \Phplrt\Compiler\Node\Declaration\RuleDeclaration(
            name: $name->value,
            body: $body,
            reducer: $reducer,
            isKept: $isKept,
            annotations: $annotations,
            offset: $name->offset,
            length: \max(0, $body->offset + $body->length - $name->offset),
        );
    }

    private static function reduceKeptMarker(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        return true;
    }

    private static function reduceAnnotation(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        \assert(\is_array($children));

        $name = \array_shift($children);

        \assert($name instanceof \Phplrt\Lexer\Token\Token);

        // The "@" opening the annotation belongs to the grammar rather than to the
        // name, so the name is captured apart from it
        $identifier = $name->captures[0] ?? '';

        \assert($identifier !== '', 'The name is captured by the token the annotation is read as');

        $arguments = [];
        $last = $name;

        foreach ($children as $argument) {
            \assert($argument instanceof \Phplrt\Contracts\Lexer\TokenInterface);

            // The quotes surrounding a value belong to the grammar rather than to
            // the value, and a quote of the value is written escaped for the very
            // same reason
            $arguments[] = \str_replace('\\"', '"', \substr($argument->value, 1, -1));

            $last = $argument;
        }

        return new \Phplrt\Compiler\Node\Annotation(
            name: $identifier,
            arguments: $arguments,
            offset: $name->offset,
            length: \max(0, $last->offset + $last->size - $name->offset),
        );
    }

    private static function reduceAlternation(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        \assert(\is_array($children));

        $statements = [];

        foreach ($children as $statement) {
            \assert($statement instanceof \Phplrt\Compiler\Node\Statement\Statement);

            $statements[] = $statement;
        }

        \assert($statements !== [], 'A production recognizes at least one statement');

        if (!isset($statements[1])) {
            return $statements[0];
        }

        $last = $statements[\count($statements) - 1];

        return new \Phplrt\Compiler\Node\Statement\Alternation(
            statements: $statements,
            offset: $statements[0]->offset,
            length: \max(0, $last->offset + $last->length - $statements[0]->offset),
        );
    }

    private static function reduceConcatenation(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        \assert(\is_array($children));

        $statements = [];

        foreach ($children as $statement) {
            \assert($statement instanceof \Phplrt\Compiler\Node\Statement\Statement);

            $statements[] = $statement;
        }

        \assert($statements !== [], 'A production recognizes at least one statement');

        if (!isset($statements[1])) {
            return $statements[0];
        }

        $last = $statements[\count($statements) - 1];

        return new \Phplrt\Compiler\Node\Statement\Concatenation(
            statements: $statements,
            offset: $statements[0]->offset,
            length: \max(0, $last->offset + $last->length - $statements[0]->offset),
        );
    }

    private static function reduceAdjacency(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        \assert($children instanceof \Phplrt\Lexer\Token\Token);

        return new \Phplrt\Compiler\Node\Statement\Adjacency(
            offset: $children->offset,
            length: $children->size,
        );
    }

    private static function reduceElement(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        \assert(\is_array($children));

        $annotations = [];

        // What is said about the statement is written after it, so it is read off
        // the back until the statement itself is reached
        while (($annotation = $children[\count($children) - 1] ?? null) instanceof \Phplrt\Compiler\Node\Annotation) {
            \array_unshift($annotations, $annotation);

            \array_pop($children);
        }

        $sign = $children[0] ?? null;
        $statement = $children[1] ?? null;

        if ($statement === null) {
            \assert($sign instanceof \Phplrt\Compiler\Node\Statement\Statement);

            $statement = $sign;
        } else {
            \assert($sign instanceof \Phplrt\Contracts\Lexer\TokenInterface);
            \assert($statement instanceof \Phplrt\Compiler\Node\Statement\Statement);

            $statement = new \Phplrt\Compiler\Node\Statement\Predicate(
                statement: $statement,
                isExpected: $sign->value === '&',
                offset: $sign->offset,
                length: \max(0, $statement->offset + $statement->length - $sign->offset),
            );
        }

        if ($annotations === []) {
            return $statement;
        }

        $last = $annotations[\count($annotations) - 1];

        return new \Phplrt\Compiler\Node\Statement\Annotated(
            statement: $statement,
            annotations: $annotations,
            offset: $statement->offset,
            length: \max(0, $last->offset + $last->length - $statement->offset),
        );
    }

    private static function reduceSuffixed(\Phplrt\Parser\Context $ctx, mixed $children): mixed
    {
        \assert(\is_array($children));

        $statement = $children[0] ?? null;
        $quantifier = $children[1] ?? null;

        \assert($statement instanceof \Phplrt\Compiler\Node\Statement\Statement);

        if (!$quantifier instanceof \Phplrt\Compiler\Node\Statement\Quantifier) {
            return $statement;
        }

        return new \Phplrt\Compiler\Node\Statement\Repetition(
            statement: $statement,
            quantifier: $quantifier,
            offset: $statement->offset,
            length: \max(0, $quantifier->offset + $quantifier->length - $statement->offset),
        );
    }

